
import type { BuyerPauseCapability } from './BuyerPauseCapability.js';
import type { BuyerRetentionOffer } from './BuyerRetentionOffer.js';

/** What a store lets buyers do to their own subscriptions. Send at least one field; each field you omit takes its default. */ export type BuyerCapabilities = { /** Reasons a buyer is asked to choose from when canceling, in the order shown. Empty: the buyer is not asked. When the list is not empty, a buyer's cancellation_reason_code must be one of them. maxItems: 8. */ "cancellation_reasons"?: Array<"too_expensive" | "missing_features" | "switched_service" | "unused" | "customer_service" | "too_complex" | "low_quality" | "other" | (string & {})>; /** When a subscription a buyer cancels ends. end_of_period: when the current billing period ends. buyer_chooses: the buyer picks the end of the period or right away. A trialing, paused, or incomplete subscription, or one whose first paid period never started, ends right away either way. */ "cancellation_timing"?: "end_of_period" | "buyer_chooses" | (string & {}); /** Whether buyers may pause, and for how long. Omit it to let buyers pause with no limit. */ "pause"?: BuyerPauseCapability; /** The offer a buyer sees before canceling. The buyer can always decline it and cancel. Omit it for no offer. */ "retention_offer"?: BuyerRetentionOffer; };
